('about.story_heading', 'About page', 'Story heading', 'One system for the cash desk, storeroom, customer and manager.'),
('about.story_copy', 'About page', 'Story paragraph', 'Flexi Retail Software is an all-in-one retail management platform built for Nigerian retail businesses. From barcode scanning at the front desk to expiry alerts in the storeroom and delivery tracking for online orders, Flexi replaces paper records, scattered spreadsheets and guesswork with a single source of truth.'),
('about.promise_heading', 'About page', 'Promise heading', 'Accurate stock. Clear accountability.'),
('about.promise_copy', 'About page', 'Promise paragraph', 'Completed sales reduce stock automatically, prices are enforced by the server, and each sale is attributed to the signed-in cashier. Role-based access gives administrators, cashiers and customers the permissions relevant to them.'),
('about.button', 'About page', 'Story button', 'Explore the features'),
('about.approach_eyebrow', 'About page', 'Approach eyebrow', 'A better day in store'),
('about.approach_heading', 'About page', 'Approach heading', 'Web-based, secure and designed to protect data integrity.'),
('about.approach_copy', 'About page', 'Approach paragraph', 'Run Flexi in a browser on desktop, tablet or mobile with no per-machine installation. Server-enforced pricing, hashed credentials, expiring access tokens, role checks on every request, and atomic sales, stock and order transactions help protect access and data integrity.'),
('features.title', 'Features page', 'Browser title', 'Retail software features'),
('features.description', 'Features page', 'Search description', 'Explore point of sale, inventory, receipts, order fulfilment, customer shop, staff access, vendor, waste and analytics modules.'),
