('features.title_sales', 'Features page', 'Sales feature title', 'Point of sale'),
('features.copy_sales', 'Features page', 'Sales feature description', 'A fast, keyboard- and scanner-friendly till. Add products by barcode, SKU or product name, manage quantities and discounts, and accept cash, POS or transfer payments. Completed sales deduct stock immediately.'),
