('features.image_alt_sales', 'Features page', 'Sales image description', 'A cashier assisting a customer at checkout'),
('features.title_inventory', 'Features page', 'Inventory feature title', 'Inventory & product management'),
('features.copy_inventory', 'Features page', 'Inventory feature description', 'Manage a searchable product catalogue with SKUs, barcodes, variants and stock levels. Track expiry dates with advance warnings, import product lists from Excel and control which products cashiers can sell.'),
('features.icon_inventory', 'Features page', 'Inventory feature icon', 'fas fa-boxes'),
('features.image_inventory', 'Features page', 'Inventory image path', 'assets/images/stock-scanning.jpg'),
