('features.copy_shop', 'Features page', 'Customer shop feature description', 'Give customers an online catalogue to browse, add to cart and order. In-store scan-and-pay supports self-checkout with a cart, receipt and order record.'),
('features.icon_shop', 'Features page', 'Customer shop feature icon', 'fas fa-qrcode'),
