('features.title_customers', 'Features page', 'Customer feature title', 'Customer management'),
('features.copy_customers', 'Features page', 'Customer feature description', 'Build customer profiles from their orders, review last purchase and lifetime spend, and prepare SMS, email or WhatsApp promotions for customer segments.'),
