CREATE DATABASE IF NOT EXISTS flexi_retail
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE flexi_retail;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS site_content (
  content_key VARCHAR(120) NOT NULL PRIMARY KEY,
  content_group VARCHAR(80) NOT NULL,
  content_label VARCHAR(160) NOT NULL,
  content_value TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_users (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  username VARCHAR(80) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inquiries (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  inquiry_type ENUM('contact', 'demo') NOT NULL,
  sender_name VARCHAR(120) NOT NULL,
  sender_email VARCHAR(254) NOT NULL,
  company VARCHAR(160) NOT NULL DEFAULT '',
  message TEXT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX inquiries_created_at (created_at),
  INDEX inquiries_sender_email (sender_email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  content_group = VALUES(content_group),
  content_label = VALUES(content_label);
